INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4208494, 605990, 39349, '<td valign="top">Okay, I really like where you are going with this shot. <br/> <br/>Couple of things that I feel might help out here. First, get lower to the ground, show me life at the shoes perspective. The angles you''ve chosen here help the composition IMHO but again, a lower angle would create a more dramatic effect. <br/> <br/>Secondly, I''d opt for a b/w version of this shot, it''s begging for deep rich tones that would really work nicely with the ribbons and reflections on the shoes. <br/> <br/>Great work and I wish you luck in the challenge.</td>', 'Okay, I really like where you are going with this shot.  Couple of things that I feel might help out here. First, get lower to the ground, show me life at the shoes perspective. The angles you''ve chosen here help the composition IMHO but again, a lower angle would create a more dramatic effect.  Secondly, I''d opt for a b/w version of this shot, it''s begging for deep rich tones that would really work nicely with the ribbons and reflections on the shoes.  Great work and I wish you luck in the challenge.', '2007-10-31 12:31:52.000000', NULL, 1),
(4208496, 606250, 39349, '<td valign="top">Nice perspective!</td>', 'Nice perspective!', '2007-10-31 12:32:06.000000', NULL, 1),
(4208498, 604740, 39349, '<td valign="top">?</td>', '?', '2007-10-31 12:32:25.000000', NULL, 1),
(4208506, 604866, 39349, '<td valign="top">Great use of DOF. Nice composition, and tones but I''m left wondering where these pod are coming from. They feel like they are just floating in mid air.<br/>7</td>', 'Great use of DOF. Nice composition, and tones but I''m left wondering where these pod are coming from. They feel like they are just floating in mid air.7', '2007-10-31 12:34:11.000000', NULL, 1),
(4208523, 606637, 73235, '<td valign="top">not very favorable lighting, a bit more light to the bottom would show more feature of the flower. Good complementary color in the background</td>', 'not very favorable lighting, a bit more light to the bottom would show more feature of the flower. Good complementary color in the background', '2007-10-31 12:43:02.000000', NULL, 1),
