(4208845, 606562, 41409, '<td valign="top">The detail in this shot is very good, but the orientation of the ring is somewhat bland.  A quick rotation for a more dramatic view and this one would be absolutely fantastic.</td>', 'The detail in this shot is very good, but the orientation of the ring is somewhat bland.  A quick rotation for a more dramatic view and this one would be absolutely fantastic.', '2007-10-31 15:00:21.000000', NULL, 1),
(4208849, 604441, 41409, '<td valign="top">I like this one a lot.  Especially the amount of detail you''ve managed to maintain in the foreground.  The only thing I don''t like is the border, it stands out too much.</td>', 'I like this one a lot.  Especially the amount of detail you''ve managed to maintain in the foreground.  The only thing I don''t like is the border, it stands out too much.', '2007-10-31 15:01:28.000000', NULL, 1),
