(4208857, 606426, 41409, '<td valign="top">Great shot!  The only improvement I could offer would be to have less of the foreground before the flower comes into the image.</td>', 'Great shot!  The only improvement I could offer would be to have less of the foreground before the flower comes into the image.', '2007-10-31 15:03:28.000000', NULL, 1),
(4208860, 606530, 41409, '<td valign="top">I like the high key look in this one.  You''ve managed to keep a lot of the detail in the foreground, but it''s almost too overpowering overall.</td>', 'I like the high key look in this one.  You''ve managed to keep a lot of the detail in the foreground, but it''s almost too overpowering overall.', '2007-10-31 15:04:18.000000', NULL, 1),
(4208862, 605561, 41409, '<td valign="top">Good shot, I like the detail and composition you''ve got here.  The only thing I don''t really like is the orange tint.  Overall a good one though.</td>', 'Good shot, I like the detail and composition you''ve got here.  The only thing I don''t really like is the orange tint.  Overall a good one though.', '2007-10-31 15:05:04.000000', NULL, 1),
