INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4226702, 606512, 37252, '<td valign="top">Very cute shot. I wish the pups had started to climb out of the basket just a tad further, but it''s still a good shot. Your lighting is perfect as the black pup has his/her face properly exposed. Black dogs are extra difficult.</td>', 'Very cute shot. I wish the pups had started to climb out of the basket just a tad further, but it''s still a good shot. Your lighting is perfect as the black pup has his/her face properly exposed. Black dogs are extra difficult.', '2007-11-06 23:12:20.000000', NULL, 1),
(4226703, 606075, 37252, '<td valign="top">Simple, elegant, very clean</td>', 'Simple, elegant, very clean', '2007-11-06 23:12:44.000000', NULL, 1),
(4226707, 606617, 37252, '<td valign="top">What a cutie! Love the pose. Nice softness to the focus - lets me sense the feel of the pup.</td>', 'What a cutie! Love the pose. Nice softness to the focus - lets me sense the feel of the pup.', '2007-11-06 23:13:43.000000', NULL, 1),
(4226708, 606530, 37252, '<td valign="top">Very adorable</td>', 'Very adorable', '2007-11-06 23:14:13.000000', NULL, 1),
(4226709, 604441, 37252, '<td valign="top">This shot really had a good chance at a ribbon...until you added that frame. Sorry - but in my opinion it ruins the shot. I''m going to try and ignore the frame and still give you a 7</td>', 'This shot really had a good chance at a ribbon...until you added that frame. Sorry - but in my opinion it ruins the shot. I''m going to try and ignore the frame and still give you a 7', '2007-11-06 23:14:28.000000', NULL, 1),
(4226714, 606346, 37252, '<td valign="top">Excellent capture. Not often do people capture facial expression on birds. The motion of the wing is good too, as it keeps my eye drawn to the face more.</td>', 'Excellent capture. Not often do people capture facial expression on birds. The motion of the wing is good too, as it keeps my eye drawn to the face more.', '2007-11-06 23:15:35.000000', NULL, 1),
(4226715, 604849, 37252, '<td valign="top">nice backlighting</td>', 'nice backlighting', '2007-11-06 23:15:52.000000', NULL, 1),
(4226716, 606662, 37252, '<td valign="top">I would prefer to see the lighting on the leafs instead of the stalk. Just my own personal preference.</td>', 'I would prefer to see the lighting on the leafs instead of the stalk. Just my own personal preference.', '2007-11-06 23:16:51.000000', NULL, 1),
(4226718, 606562, 37252, '<td valign="top">Sharp focus! I never have very good luck photographing jewelry - you have done well here.</td>', 'Sharp focus! I never have very good luck photographing jewelry - you have done well here.', '2007-11-06 23:17:32.000000', NULL, 1),
(4226735, 604740, 37252, '<td valign="top">DNMC</td>', 'DNMC', '2007-11-06 23:23:11.000000', NULL, 1),
(4226736, 605941, 37252, '<td valign="top">I gave this a three, and only feel it is fair to explain why. The focus is too soft, poor lighting on your subject matter, and undesirable crop. Overall it lacks interest to me.</td>', 'I gave this a three, and only feel it is fair to explain why. The focus is too soft, poor lighting on your subject matter, and undesirable crop. Overall it lacks interest to me.', '2007-11-06 23:23:14.000000', NULL, 1),
