(4234009, 606725, 27482, '<td valign="top">Congrats on the new PB dude and the ribbon, think this shot is pretty cool, especially the angle/composition and also the "ghosts" in the upper right corner.</td>', 'Congrats on the new PB dude and the ribbon, think this shot is pretty cool, especially the angle/composition and also the "ghosts" in the upper right corner.', '2007-11-09 04:22:16.000000', NULL, 0),
(4234010, 606826, 27482, '<td valign="top">Well you certainly don´t fool around or waste shot´s/opportunities, hehe, congrats!  Reminds me when I took my postcard and free study red ribbon winners last year only 1 minute apart and standing in the same place :)</td>', 'Well you certainly don´t fool around or waste shot´s/opportunities, hehe, congrats!  Reminds me when I took my postcard and free study red ribbon winners last year only 1 minute apart and standing in the same place :)', '2007-11-09 04:23:26.000000', NULL, 0),
